#!/usr/bin/env python3
"""Embed pinned BYOD Fuzz Machine weights; no runtime files or JSON parsing."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent

def numbers(value):
    if isinstance(value, list):
        return "{" + ",".join(numbers(x) for x in value) + "}"
    return format(value, ".9e") + "f"

lines = ["// Generated by models/generate.py from BYOD weights (GPL-3.0).",
         "// See ../SOURCES.md. Do not edit by hand.", "#pragma once",
         "namespace audition {", "struct FuzzWeights {",
         "float input[96][2], recurrent[96][24], bias[96], output[24], outputBias;", "};"]
for name in ("fuzz_15", "fuzz_2", "fuzz_15_88", "fuzz_2_88"):
    model = json.loads((ROOT / (name + ".json")).read_text())
    assert model["model_data"]["hidden_size"] == 24
    state = model["state_dict"]
    biases = [a + b for a, b in zip(state["rec.bias_ih_l0"], state["rec.bias_hh_l0"])]
    values = [state["rec.weight_ih_l0"], state["rec.weight_hh_l0"], biases,
              state["lin.weight"][0], state["lin.bias"][0]]
    lines.append("inline constexpr FuzzWeights " + name + " = {\n" + ",\n".join(numbers(v) for v in values) + "\n};")
lines.append("} // namespace audition")
(ROOT / "weights.h").write_text("\n".join(lines) + "\n")
